using Microsoft.AspNetCore.Localization;
using Microsoft.Extensions.Options;
using System.Globalization;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllersWithViews()
    .AddViewLocalization(LanguageViewLocationExpanderFormat.Suffix)
    .AddDataAnnotationsLocalization();

builder.Services.Configure<RequestLocalizationOptions>(options =>
{
    var supportedCultures = new[]
    {
        new CultureInfo("en-US"),
        new CultureInfo("fr-FR"),
        new CultureInfo("es-ES")
    };
    options.DefaultRequestCulture = new RequestCulture("en-US");
    options.SupportedCultures = supportedCultures;
    options.SupportedUICultures = supportedCultures;
    // Order matters — providers are tried in sequence
    options.RequestCultureProviders = new IRequestCultureProvider[]
    {
        new QueryStringRequestCultureProvider(),
        new CookieRequestCultureProvider(),
        new AcceptLanguageHeaderRequestCultureProvider()
    };
});

var app = builder.Build();
app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();

var locOptions = app.Services.GetRequiredService<IOptions<RequestLocalizationOptions>>();
app.UseRequestLocalization(locOptions.Value);

app.UseAuthorization();
app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");
app.Run();

@using Microsoft.AspNetCore.Localization
@inject IOptions<RequestLocalizationOptions> LocOptions
@{ var requestCulture = Context.Features.Get<IRequestCultureFeature>(); var cultureItems = LocOptions.Value.SupportedUICultures .Select(c => new SelectListItem { Value = c.Name, Text = c.EnglishName }) .ToList(); }
<div class="card p-4">
    <h2>Culture Demo</h2>
    <p><strong>Culture:</strong> @requestCulture.RequestCulture.Culture.Name</p>
    <p><strong>Date:</strong> @DateTime.Now.ToLongDateString()</p>
    <p><strong>Currency:</strong> @(12345.67.ToString("C"))</p>
    <p><strong>Number:</strong> @(9876.54m.ToString("N2"))</p>
    <p><strong>Percent:</strong> @(0.856.ToString("P"))</p>
</div>
<form id="cultureForm">
    <label>Language:</label>
    <select name="culture" onchange="this.form.submit()">
        @foreach (var item in cultureItems)
        {
            <option value="@item.Value" selected="@(item.Value == requestCulture.RequestCulture.UICulture.Name)">
                @item.Text
            </option>
        }
    </select>
</form>

using Microsoft.AspNetCore.Localization;
using Microsoft.Extensions.Options;

public class HomeController : Controller
{
    private readonly RequestLocalizationOptions _locOptions;

    public HomeController(IOptions<RequestLocalizationOptions> locOptions)
    {
        _locOptions = locOptions.Value;
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public IActionResult SetLanguage(string culture, string returnUrl)
    {
        // Validate culture is in the supported list
        var cultureInfo = _locOptions.SupportedCultures
            .FirstOrDefault(c => c.Name == culture);
        if (cultureInfo == null)
        {
            culture = _locOptions.DefaultRequestCulture.Culture.Name;
        }

        Response.Cookies.Append(
            CookieRequestCultureProvider.DefaultCookieName,
            CookieRequestCultureProvider.MakeCookieValue(
                new RequestCulture(culture)),
            new CookieOptions
            {
                Expires = DateTimeOffset.UtcNow.AddMonths(1),
                IsEssential = true
            }
        );

        return LocalRedirect(returnUrl ?? "/");
    }
}

using Microsoft.AspNetCore.Localization;
using Microsoft.Extensions.Options;
using System.Globalization;

builder.Services.Configure<RequestLocalizationOptions>(options =>
{
    var supportedCultures = new[]
    {
        new CultureInfo("en-US"),
        new CultureInfo("fr-FR"),
        new CultureInfo("es-ES")
    };
    options.DefaultRequestCulture = new RequestCulture("en-US");
    options.SupportedCultures = supportedCultures;
    options.SupportedUICultures = supportedCultures;

    // Custom provider: first URL segment is the culture code
    options.AddInitialRequestCultureProvider(new CustomRequestCultureProvider(
        async context =>
        {
            var segments = context.Request.Path.Value?.Split('/', StringSplitOptions.RemoveEmptyEntries);
            if (segments != null && segments.Length > 0)
            {
                var candidate = segments[0];
                if (supportedCultures.Any(c => c.Name.Equals(candidate, StringComparison.OrdinalIgnoreCase)))
                {
                    return await Task.FromResult(new ProviderCultureResult(candidate));
                }
            }
            return await Task.FromResult<ProviderCultureResult?>(null);
        }
    ));
});

using Microsoft.AspNetCore.Localization;
using Microsoft.AspNetCore.Identity;
using System.Globalization;

public class UserCultureProvider : RequestCultureProvider
{
    private readonly UserManager<ApplicationUser> _userManager;

    public UserCultureProvider(UserManager<ApplicationUser> userManager)
    {
        _userManager = userManager;
    }

    public override async Task<ProviderCultureResult?> DetermineProviderCultureResult(HttpContext context)
    {
        if (context.User.Identity?.IsAuthenticated != true)
            return await Task.FromResult<ProviderCultureResult?>(null);

        var user = await _userManager.GetUserAsync(context.User);
        if (string.IsNullOrEmpty(user?.PreferredCulture))
            return await Task.FromResult<ProviderCultureResult?>(null);

        return await Task.FromResult(
            new ProviderCultureResult(user.PreferredCulture, user.PreferredUICulture));
    }
}
